const socket=io();let me=null,roomId=null,people=[];const list=document.querySelector('#conversationList'),area=document.querySelector('#messageArea'),input=document.querySelector('#messageInput'),toast=document.querySelector('#toast'),dialog=document.querySelector('#roomDialog');
const palette=['amber','violet','sky','rose'];function styleFor(name){return palette[(name.charCodeAt(0)||0)%palette.length]}function avatar(name,small=false){return `<div class="avatar avatar-${styleFor(name)} ${small?'small':''}">${name.slice(0,1).toUpperCase()}</div>`}function notify(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2100)}function renderPeople(){list.innerHTML=people.map((name,i)=>`<div class="conversation ${name===me?'active':''}">${avatar(name)}<span><strong>${name}${name===me?' (you)':''}</strong><p>${name===me?'You are connected':'Online now'}</p></span><time>${i===0?'●':''}</time></div>`).join('')||'<p class="empty">No one else is here yet.</p>'}function updateRoom(){let count=people.length;document.querySelector('#chatTitle').textContent=roomId?`Room ${roomId}`:'Welcome to ManjuConnect';document.querySelector('#headerAvatar').textContent=roomId?'#':'?';document.querySelector('#chatPresence').innerHTML=roomId?`<i></i> ${count} ${count===1?'person':'people'} online`:'<i></i> Connect to a room to chat';document.querySelector('#profileName').textContent=me||'Not connected';document.querySelector('#profileInitial').textContent=me?me[0].toUpperCase():'?';document.querySelector('#profileStatus').textContent=roomId?`Room ${roomId}`:'Choose a room';renderPeople()}function addMessage(msg){let who=msg.name===me?'me':'them';let article=document.createElement('article');article.className=`message ${who}`;article.innerHTML=`${avatar(msg.name,true)}<div class="bubble">${msg.name!==me?`<b>${escapeHtml(msg.name)}</b><br>`:''}${escapeHtml(msg.text)}<time class="time">${msg.timestamp}${who==='me'?' · ✓✓':''}</time></div>`;area.append(article);area.scrollTop=area.scrollHeight}function escapeHtml(s){let div=document.createElement('div');div.textContent=s;return div.innerHTML}function showSystem(text){let marker=document.createElement('p');marker.className='day-marker';marker.textContent=text;area.append(marker);area.scrollTop=area.scrollHeight}function resetMessages(){area.innerHTML='<p class="day-marker">LIVE CHAT</p>'}function send(){let text=input.value.trim();if(!text||!roomId)return;socket.emit('send-message',text);input.value='';socket.emit('stop-typing')}document.querySelector('#composer').onsubmit=e=>{e.preventDefault();send()};input.oninput=()=>{if(roomId)socket.emit('typing')};document.querySelector('#search').oninput=e=>{let filter=e.target.value.toLowerCase();list.querySelectorAll('.conversation').forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(filter))};document.querySelector('#mobileMenu').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#newChat').onclick=()=>{dialog.showModal();document.querySelector('#roomInput').value=''};document.querySelector('.emoji').onclick=()=>{input.value+=' 😊';input.focus()};document.querySelector('.attach').onclick=()=>notify('File sharing can be added next.');document.querySelector('#inviteButton').onclick=()=>roomId?notify(`Share room code: ${roomId}`):dialog.showModal();document.querySelector('#roomForm').onsubmit=e=>{e.preventDefault();let name=document.querySelector('#nameInput').value.trim(),code=document.querySelector('#roomInput').value.trim();if(!name)return;socket.emit(code?'join-room':'create-room',{name,roomId:code},reply=>{if(!reply.ok)return notify(reply.error);me=name;roomId=reply.roomId;dialog.close();resetMessages();updateRoom();notify(`Connected to room ${roomId}`)})};socket.on('room-history',data=>{people=data.people;resetMessages();data.messages.forEach(addMessage);updateRoom()});socket.on('room-users',data=>{people=data.people;updateRoom()});socket.on('receive-message',addMessage);socket.on('system-message',showSystem);socket.on('user-typing',text=>{let typing=document.querySelector('#typing');typing.textContent=text;typing.classList.toggle('show',!!text)});dialog.showModal();
